"use client"

import * as React from "react"

import { findGlyph, getMask, type GridMask } from "./patterns"
import {
  SHAPE_STYLES,
  sampleColor,
  type GridLoaderColorMode,
  type GridLoaderEffect,
  type GridLoaderShape,
} from "./styles"
import { GRID_LOADER_DEFAULTS, GRID_LOADER_DOT_SIZE_RATIO } from "./defaults"
import { injectGridLoaderStyles } from "./inject-styles"
import {
  DEFAULT_VARIANT,
  computePhases,
  createCellContext,
  sequenceToPhases,
  type GridLoaderVariant,
  type MaskMotion,
} from "./variants"

type CssVars = React.CSSProperties & Record<`--${string}`, string | number>

const MIN_GRID = 2
const MAX_GRID = 12

export interface GridLoaderProps extends Omit<React.ComponentProps<"span">, "color"> {
  /** Animation pattern. */
  variant?: GridLoaderVariant
  /** Number of rows and columns (2–12). */
  gridSize?: number
  /** Size of each grid cell, in pixels. */
  cellSize?: number
  /** Alias of `cellSize`, kept for backwards compatibility. */
  size?: number
  /** Size of the dot inside a cell, in pixels. Defaults to `cellSize × 0.875`. */
  dotSize?: number
  /** Space between cells, in pixels. */
  gap?: number
  /** Duration of one full cycle, in seconds. */
  speed?: number
  /** Base color, or the first stop when `colors` is omitted. */
  color?: string
  /** Color ramp sampled according to `colorMode`. */
  colors?: readonly string[]
  /** How `colors` is mapped onto the grid. */
  colorMode?: GridLoaderColorMode
  /** Keyframes applied to every dot. */
  effect?: GridLoaderEffect
  /** Dot silhouette. */
  shape?: GridLoaderShape
  /** CSS timing function. */
  easing?: string
  /** Opacity at the resting point of the cycle. */
  minOpacity?: number
  /** Opacity at the peak of the cycle. */
  maxOpacity?: number
  /** Scale at the resting point of the cycle. */
  minScale?: number
  /** Scale at the peak of the cycle. */
  maxScale?: number
  /** Blur radius of the dot glow, in pixels. */
  glow?: number
  /** How much of the cycle the stagger spans (1 = a full cycle). */
  spread?: number
  /** Extra phase offset, in cycles. */
  offset?: number
  /** Plays the stagger backwards. */
  reverse?: boolean
  /** CSS animation direction. */
  direction?: React.CSSProperties["animationDirection"]
  /** Freezes the animation. */
  paused?: boolean
  /** Rendering of cells that are not part of the shape. */
  inactive?: "dim" | "hidden" | "solid"
  /** Opacity used when `inactive` is `"dim"`. */
  inactiveOpacity?: number
  /** Color used for inactive cells. Defaults to the active color. */
  inactiveColor?: string
  /** Custom bitmap that overrides the variant shape. */
  mask?: GridMask | string | null
  /**
   * Ordered cell indices (`row * gridSize + col`). Animation delay follows this
   * list; cells not listed stay inactive. Takes precedence over `variant`/`mask`.
   */
  sequence?: readonly number[]
  /** Drawing order used by glyph and custom-mask variants. */
  maskMotion?: MaskMotion
  /** Accessible label announced to screen readers. */
  label?: string
  /** Disables the animation when the user asks for reduced motion. */
  respectReducedMotion?: boolean
}

function clamp(value: number, min: number, max: number) {
  return value < min ? min : value > max ? max : value
}

function colorPosition(mode: GridLoaderColorMode, cellIndex: number, n: number): number {
  const cell = createCellContext(cellIndex, n)
  switch (mode) {
    case "horizontal":
      return cell.colN
    case "vertical":
      return cell.rowN
    case "diagonal":
      return (cell.colN + cell.rowN) / 2
    case "radial":
      return cell.dist
    case "angular":
      return cell.angle
    case "random":
      return cell.rand
    default:
      return 0
  }
}

/** Keyframes are injected automatically when this module loads on the client. */
injectGridLoaderStyles()

export function GridLoader({
  className,
  style,
  variant = DEFAULT_VARIANT,
  gridSize = GRID_LOADER_DEFAULTS.gridSize,
  cellSize,
  size,
  dotSize,
  gap = GRID_LOADER_DEFAULTS.gap,
  speed = GRID_LOADER_DEFAULTS.speed,
  color = GRID_LOADER_DEFAULTS.color,
  colors,
  colorMode = GRID_LOADER_DEFAULTS.colorMode,
  effect = GRID_LOADER_DEFAULTS.effect,
  shape = GRID_LOADER_DEFAULTS.shape,
  easing = GRID_LOADER_DEFAULTS.easing,
  minOpacity = GRID_LOADER_DEFAULTS.minOpacity,
  maxOpacity = GRID_LOADER_DEFAULTS.maxOpacity,
  minScale = GRID_LOADER_DEFAULTS.minScale,
  maxScale = GRID_LOADER_DEFAULTS.maxScale,
  glow = GRID_LOADER_DEFAULTS.glow,
  spread = GRID_LOADER_DEFAULTS.spread,
  offset = GRID_LOADER_DEFAULTS.offset,
  reverse = GRID_LOADER_DEFAULTS.reverse,
  direction = GRID_LOADER_DEFAULTS.direction,
  paused = GRID_LOADER_DEFAULTS.paused,
  inactive = GRID_LOADER_DEFAULTS.inactive,
  inactiveOpacity = GRID_LOADER_DEFAULTS.inactiveOpacity,
  inactiveColor,
  mask = null,
  sequence,
  maskMotion = GRID_LOADER_DEFAULTS.maskMotion,
  label = GRID_LOADER_DEFAULTS.label,
  respectReducedMotion = GRID_LOADER_DEFAULTS.respectReducedMotion,
  ...props
}: GridLoaderProps) {
  const n = Math.round(clamp(gridSize, MIN_GRID, MAX_GRID))
  const cell = Math.max(1, cellSize ?? size ?? GRID_LOADER_DEFAULTS.cellSize)
  const dot = Math.max(1, dotSize ?? cell * GRID_LOADER_DOT_SIZE_RATIO)
  const duration = Math.max(0.05, speed)
  const ramp = React.useMemo<readonly string[]>(
    () => (colors && colors.length > 0 ? colors : [color]),
    [colors, color]
  )

  const phases = React.useMemo(
    () =>
      sequence
        ? sequenceToPhases(sequence, n, { reverse, spread })
        : computePhases(variant, n, { maskMotion, mask, reverse, spread }),
    [sequence, variant, n, maskMotion, mask, reverse, spread]
  )

  const shapeStyle = SHAPE_STYLES[shape] ?? SHAPE_STYLES.circle
  const dotHeight = dot * (shapeStyle.heightScale ?? 1)
  const borderWidth = shapeStyle.outlined ? Math.max(1, dot * 0.22) : 0

  const containerStyle: CssVars = {
    display: "inline-grid",
    verticalAlign: "middle",
    gridTemplateColumns: `repeat(${n}, ${cell}px)`,
    gridAutoRows: `${cell}px`,
    gap: `${gap}px`,
    width: "fit-content",
    lineHeight: 0,
    "--gl-o0": minOpacity,
    "--gl-o1": maxOpacity,
    "--gl-s0": minScale,
    "--gl-s1": maxScale,
    "--gl-shift": `${Math.max(1, cell * 0.6)}px`,
    "--gl-glow-strong": `${Math.max(glow, dot * 0.9)}px`,
    "--gl-glow-color": sampleColor(ramp, 0.5),
    ...style,
  }

  return (
    <span
      data-slot="grid-loader"
      data-variant={variant}
      data-effect={effect}
      data-reduced-motion={respectReducedMotion ? "true" : "false"}
      role="status"
      aria-label={label}
      aria-busy={!paused}
      className={className}
      style={containerStyle}
      {...props}
    >
      {phases.map((phase, index) => {
        const isActive = phase !== null
        const position = colorMode === "cycle" ? 0 : colorPosition(colorMode, index, n)
        const dotColor =
          colorMode === "cycle" ? ramp[index % ramp.length] : sampleColor(ramp, position)
        const resolvedColor = isActive ? dotColor : (inactiveColor ?? dotColor)

        const dotStyle: CssVars = {
          display: "block",
          width: `${dot}px`,
          height: `${dotHeight}px`,
          borderRadius: shapeStyle.borderRadius,
          clipPath: shapeStyle.clipPath,
          backgroundColor: shapeStyle.outlined ? "transparent" : resolvedColor,
          border: shapeStyle.outlined ? `${borderWidth}px solid ${resolvedColor}` : undefined,
          boxSizing: "border-box",
          "--gl-o0": minOpacity,
          "--gl-o1": maxOpacity,
          "--gl-s0": minScale,
          "--gl-s1": maxScale,
        }

        if (isActive) {
          const delay = (((phase + offset) % 1) + 1) % 1
          dotStyle.animationName = `gl-${effect}`
          dotStyle.animationDuration = `${duration}s`
          dotStyle.animationTimingFunction = easing
          dotStyle.animationDelay = `${(delay * duration).toFixed(4)}s`
          dotStyle.animationIterationCount = "infinite"
          dotStyle.animationDirection = direction
          dotStyle.animationFillMode = "backwards"
          dotStyle.animationPlayState = paused ? "paused" : "running"
          if (glow > 0 && effect !== "glow") {
            dotStyle.boxShadow = `0 0 ${glow}px ${resolvedColor}`
          }
        } else {
          dotStyle.opacity = inactive === "hidden" ? 0 : inactive === "solid" ? 1 : inactiveOpacity
        }

        return (
          <span
            key={index}
            aria-hidden="true"
            style={{
              width: `${cell}px`,
              height: `${cell}px`,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
            }}
          >
            <span data-slot="grid-loader-dot" style={dotStyle} />
          </span>
        )
      })}
    </span>
  )
}

// ---------------------------------------------------------------------------
// Text loader
// ---------------------------------------------------------------------------

export interface GridLoaderTextProps
  extends Omit<
    GridLoaderProps,
    "variant" | "mask" | "sequence" | "spread" | "offset" | "children"
  > {
  /** Text drawn with the bitmap font. Unknown characters render as a gap. */
  text: string
  /** Space between glyphs, in pixels. */
  letterGap?: number
  /** Fraction of the cycle each glyph occupies. Defaults to `1 / text.length`. */
  letterSpan?: number
  /** Draws every glyph at the same time instead of one after another. */
  simultaneous?: boolean
}

export function GridLoaderText({
  text,
  letterGap = 6,
  letterSpan,
  simultaneous = false,
  gridSize = 5,
  cellSize,
  size,
  gap = 2,
  className,
  label,
  ...props
}: GridLoaderTextProps) {
  const n = Math.round(clamp(gridSize, MIN_GRID, MAX_GRID))
  const characters = React.useMemo(() => [...text], [text])
  const drawable = characters.filter((char) => char.trim().length > 0)
  const span = letterSpan ?? 1 / Math.max(drawable.length, 1)
  const cell = Math.max(1, cellSize ?? size ?? 5)

  let drawIndex = -1

  return (
    <span
      role="status"
      aria-label={label ?? `Loading ${text}`}
      className={className}
      style={{ display: "inline-flex", alignItems: "center", gap: `${letterGap}px` }}
    >
      {characters.map((char, index) => {
        const glyph = findGlyph(char)
        if (!glyph) {
          return (
            <span
              key={`${char}-${index}`}
              aria-hidden="true"
              style={{ width: `${cell * Math.ceil(n / 2)}px` }}
            />
          )
        }
        drawIndex += 1
        const mask = getMask(`text:${char}`, glyph, n)
        return (
          <GridLoader
            key={`${char}-${index}`}
            {...props}
            aria-hidden
            gridSize={n}
            cellSize={cell}
            gap={gap}
            mask={mask}
            spread={simultaneous ? 1 : span}
            offset={simultaneous ? 0 : drawIndex * span}
          />
        )
      })}
    </span>
  )
}

