/**
 * Bitmap patterns (masks) used by the mask-based GridLoader variants.
 *
 * Every glyph declares one or more native resolutions. When the requested grid
 * size has no native bitmap, the closest one is resampled (block-OR when
 * downscaling, nearest-neighbour when upscaling).
 */

export type GridMask = readonly (readonly number[])[]

/** Native bitmaps of a glyph, keyed by grid size. */
export type MaskSet = Readonly<Record<number, GridMask>>

/** Parses `"010/111/010"` (or a multi-line string) into a mask. */
export function parseMask(source: string): GridMask {
  return source
    .trim()
    .split(/[/\n]/)
    .map((row) => row.trim())
    .filter((row) => row.length > 0)
    .map((row) => [...row].map((char) => (char === "1" || char === "#" || char === "x" ? 1 : 0)))
}

const pm = parseMask

