// ---------------------------------------------------------------------------
// Resampling
// ---------------------------------------------------------------------------

const scaleCache = new Map<string, GridMask>()

function nativeSizes(set: MaskSet): number[] {
  return Object.keys(set)
    .map(Number)
    .filter((n) => Number.isFinite(n))
    .sort((a, b) => a - b)
}

/**
 * Picks the bitmap to resample from. Exact matches win; otherwise the most
 * detailed bitmap that can be centered without leaving a lopsided border.
 */
function pickSource(set: MaskSet, n: number): number | null {
  const sizes = nativeSizes(set)
  if (sizes.length === 0) return null
  if (set[n]) return n

  const candidates = sizes.filter((s) => s < n)
  if (candidates.length === 0) return sizes[0]

  const centered = candidates.filter((s) => s >= 4 && (n - s * Math.floor(n / s)) % 2 === 0)
  const pool = centered.length > 0 ? centered : candidates
  return pool[pool.length - 1]
}

/**
 * Resamples a mask to an `n x n` grid.
 *
 * Growing a glyph replicates it by an integer factor and centers the result, so
 * strokes stay crisp instead of being smeared by fractional sampling. Shrinking
 * uses block-OR sampling, which keeps thin strokes from disappearing.
 */
export function scaleMask(src: GridMask, n: number): GridMask {
  const srcN = src.length
  if (srcN === n) return src
  const out: number[][] = []

  if (n > srcN) {
    const factor = Math.max(1, Math.floor(n / srcN))
    const scaled = srcN * factor
    const offset = Math.floor((n - scaled) / 2)
    for (let r = 0; r < n; r++) {
      const row: number[] = []
      const sy = Math.floor((r - offset) / factor)
      for (let c = 0; c < n; c++) {
        const sx = Math.floor((c - offset) / factor)
        const inside = sy >= 0 && sy < srcN && sx >= 0 && sx < srcN
        row.push(inside ? (src[sy]?.[sx] ?? 0) : 0)
      }
      out.push(row)
    }
    return out
  }

  for (let r = 0; r < n; r++) {
    const row: number[] = []
    const y0 = Math.floor((r * srcN) / n)
    const y1 = Math.max(y0 + 1, Math.ceil(((r + 1) * srcN) / n))
    for (let c = 0; c < n; c++) {
      const x0 = Math.floor((c * srcN) / n)
      const x1 = Math.max(x0 + 1, Math.ceil(((c + 1) * srcN) / n))
      let on = 0
      for (let sy = y0; sy < Math.min(y1, srcN) && !on; sy++) {
        for (let sx = x0; sx < Math.min(x1, srcN); sx++) {
          if (src[sy]?.[sx] === 1) {
            on = 1
            break
          }
        }
      }
      row.push(on)
    }
    out.push(row)
  }
  return out
}

/** Returns the mask of `set` rendered at size `n`, memoized by `cacheKey`. */
export function getMask(cacheKey: string, set: MaskSet | undefined, n: number): GridMask | null {
  if (!set) return null
  const key = `${cacheKey}@${n}`
  const cached = scaleCache.get(key)
  if (cached) return cached

  const sourceSize = pickSource(set, n)
  if (sourceSize === null) return null
  const mask = scaleMask(set[sourceSize], n)
  scaleCache.set(key, mask)
  return mask
}

/** Normalizes an arbitrary user mask (string or matrix) to an `n x n` grid. */
export function normalizeMask(mask: GridMask | string, n: number): GridMask {
  const parsed = typeof mask === "string" ? parseMask(mask) : mask
  const height = parsed.length
  if (height === 0) return scaleMask([[0]], n)
  const width = Math.max(...parsed.map((row) => row.length))
  const square: number[][] = []
  const side = Math.max(height, width)
  for (let r = 0; r < side; r++) {
    const row: number[] = []
    for (let c = 0; c < side; c++) row.push(parsed[r]?.[c] === 1 ? 1 : 0)
    square.push(row)
  }
  return scaleMask(square, n)
}

export const LETTER_KEYS = Object.keys(LETTER_PATTERNS) as LetterName[]
export const DIGIT_KEYS = Object.keys(DIGIT_PATTERNS) as DigitName[]
export const SYMBOL_KEYS = Object.keys(SYMBOL_PATTERNS) as SymbolName[]

const GLYPH_INDEX: Record<string, MaskSet> = {
  ...(LETTER_PATTERNS as Record<string, MaskSet>),
  ...(DIGIT_PATTERNS as Record<string, MaskSet>),
  ...(SYMBOL_PATTERNS as Record<string, MaskSet>),
}

/** Looks up a glyph by character (`"a"`, `"7"`) or symbol name (`"heart"`). */
export function findGlyph(name: string): MaskSet | undefined {
  return GLYPH_INDEX[name] ?? GLYPH_INDEX[name.toUpperCase()]
}
