export type GridLoaderShape = (typeof GRID_LOADER_SHAPES)[number]

export interface ShapeStyle {
  borderRadius?: string
  clipPath?: string
  /** Renders as an outline instead of a filled dot. */
  outlined?: boolean
  /** Multiplier applied to the dot height. */
  heightScale?: number
}

