// ---------------------------------------------------------------------------
// Colors
// ---------------------------------------------------------------------------

export const GRID_LOADER_COLOR_MODES = [
  "solid",
  "horizontal",
  "vertical",
  "diagonal",
  "radial",
  "angular",
  "random",
  "cycle",
] as const

export type GridLoaderColorMode = (typeof GRID_LOADER_COLOR_MODES)[number]

type Rgb = [number, number, number]

function parseHex(value: string): Rgb | null {
  const hex = value.trim().replace(/^#/, "")
  if (hex.length === 3) {
    const [r, g, b] = [...hex].map((char) => parseInt(char + char, 16))
    return Number.isNaN(r) || Number.isNaN(g) || Number.isNaN(b) ? null : [r, g, b]
  }
  if (hex.length === 6 || hex.length === 8) {
    const r = parseInt(hex.slice(0, 2), 16)
    const g = parseInt(hex.slice(2, 4), 16)
    const b = parseInt(hex.slice(4, 6), 16)
    return Number.isNaN(r) || Number.isNaN(g) || Number.isNaN(b) ? null : [r, g, b]
  }
  return null
}

const toHex = ([r, g, b]: Rgb) =>
  `#${[r, g, b].map((channel) => Math.round(channel).toString(16).padStart(2, "0")).join("")}`

/**
 * Samples a color ramp at `t` (`0..1`). Hex stops are interpolated; any other
 * notation (`currentColor`, `oklch(...)`, css variables) falls back to the
 * nearest stop so the loader never renders an invalid color.
 */
export function sampleColor(stops: readonly string[], t: number): string {
  if (stops.length === 0) return "currentColor"
  if (stops.length === 1) return stops[0]
  const clamped = t < 0 ? 0 : t > 1 ? 1 : t
  const scaled = clamped * (stops.length - 1)
  const index = Math.min(stops.length - 2, Math.floor(scaled))
  const local = scaled - index
  const from = parseHex(stops[index])
  const to = parseHex(stops[index + 1])
  if (!from || !to) return stops[Math.round(scaled)]
  return toHex([
    from[0] + (to[0] - from[0]) * local,
    from[1] + (to[1] - from[1]) * local,
    from[2] + (to[2] - from[2]) * local,
  ])
}

/** Adds an alpha channel to a hex color; returns the input untouched otherwise. */
export function withAlpha(color: string, alpha: number): string {
  const rgb = parseHex(color)
  if (!rgb) return color
  const a = Math.max(0, Math.min(1, alpha))
  return `rgba(${Math.round(rgb[0])}, ${Math.round(rgb[1])}, ${Math.round(rgb[2])}, ${a})`
}

